_PANEL_SUM_SCHEMA = "climate-grid/pcs-v1"
_PANEL_SUM_ITEM_KEYS = ("name", "result")
_PANEL_COMPARE_OUTPUT_KEYS = (
    "schema",
    "factor",
    "reference",
    "scales",
    "panels",
    "minimums",
    "thresholds",
    "data",
